    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(amount > 0);
        require(address(this).balance >= amount);
        c.depositsCount(); if (__ESBMC_reverted()) return; // read-only touch
        uint balBefore = address(c).balance;
        uint thisBefore = address(this).balance;
        c.withdrawAll(); if (__ESBMC_reverted()) return;
        assert(address(c).balance == 0 && address(this).balance == thisBefore + balBefore);
    }
    receive() external payable {}
}

